(function(){'use strict';
db.organismRateTables=db.organismRateTables||{};
if(window.ProBtpInitialRows){const ebs=db.companies.find(c=>String(c.siret||'').replace(/\s/g,'')==='93215268900018'),key=ebs&&ebs.id+'|PRO BTP';if(key&&!db.organismRateTables[key]){const parsed=OrganismExportAdapters.probtp(ProBtpInitialRows,'');const version={id:'probtp-export-initial-v1',organism:'PRO BTP',company:ebs.id,createdAt:'2026-11-14T00:00:00Z',fileName:'Feuille de taux PRO BTP fournie',rows:parsed.rows,pendingRows:parsed.pending,validityConfirmed:false};db.organismRateTables[key]={organism:'PRO BTP',company:ebs.id,activeVersionId:version.id,versions:[version]};if(!save())delete db.organismRateTables[key];}}
let pending=null;const assetsBase=new URL('.',document.currentScript.src);const parametersLabel='Paramètres';
const baseOptions=['À renseigner','gross','t1','t2','cap4','cap8','csg'];const baseNames={gross:'Brut',t1:'Tranche 1 / brut plafonné',t2:'Tranche 2',cap4:'Brut limité à 4 plafonds',cap8:'Brut limité à 8 plafonds',csg:'CSG / CRDS',manual:'Assiette renseignée'};
const tableKey=(organism)=>company+'|'+organism;
const activeTable=key=>{const t=db.organismRateTables[key];return t?.versions.find(v=>v.id===t.activeVersionId);};
const options=(headers,selected)=>'<option value="-1">Non présente / valeur commune</option>'+headers.map((h,i)=>`<option value="${i}" ${i===selected?'selected':''}>${i+1}. ${esc(String(h||'Colonne '+(i+1)).slice(0,100))}</option>`).join('');
function chooseSheet(){const data=pending;extendedForm(`<h2>Importer les taux Excel / CSV</h2><p>${esc(data.name)} · ${esc(db.companies.find(c=>c.id===company).name)}</p>`+selectField('sheetIndex','Feuille à lire','0',data.sheets.map((s,i)=>String(i)))+`<p class="wide muted">${data.sheets.map((s,i)=>esc(i+' : '+s.name)).join(' · ')}</p>`+field('headerLine','Numéro de la ligne contenant les en-têtes','1','number','min="1" max="100" required')+field('organism','Organisme / source (ex. PRO BTP, URSSAF)','PRO BTP','text','required maxlength="100"')+selectField('unit','Unité des taux du fichier','Pourcentage',['Pourcentage','Fraction Excel'])+`<p class="wide muted">Pourcentage : 6,16 signifie 6,16 %. Fraction Excel : 0,0616 signifie 6,16 %. Une cellule affichée avec % dans Excel peut contenir une fraction : vérifiez l’aperçu.</p>`+field('validFrom','Date d’effet commune si absente du fichier','','date')+field('validUntil','Fin de validité commune si absente du fichier','','date')+`<label>Assiette commune si absente du fichier<select name="baseMode">${baseOptions.map(v=>`<option value="${esc(v)}">${esc(baseNames[v]||v)}</option>`).join('')}</select></label>`+selectField('category','Catégorie commune si absente du fichier','Tous',['Tous','Ouvrier','Employé','ETAM','Cadre','Autre'])+`<label class="wide"><input name="confirmMissingZero" type="checkbox">Je confirme qu’une part salarié ou employeur absente du fichier signifie zéro pour cet import.</label><details class="wide"><summary>Voir les dix premières lignes</summary><div class="scroll"><table>${data.sheets[0].rows.slice(0,10).map((r,i)=>'<tr><th>'+String(i+1)+'</th>'+r.slice(0,12).map(v=>'<td>'+esc(v??'')+'</td>').join('')+'</tr>').join('')}</table></div></details><p class="muted">Les taux sont conservés dans ce navigateur. Aucun fichier n’est envoyé à un organisme. Formules et macros non exécutées ; fournir des valeurs. Les formats .xls, .xlsx et .csv sont pris en charge ; les PDF nécessitent un traitement distinct.</p>`,f=>{const sheet=data.sheets[Number(f.get('sheetIndex'))],headerRow=Number(f.get('headerLine'))-1;if(!sheet?.rows[headerRow])throw Error('Ligne d’en-têtes introuvable dans cette feuille.');data.sheet=sheet;data.mapping={headerRow,organism:String(f.get('organism')).trim(),unit:f.get('unit')==='Fraction Excel'?'fraction':'percent',validFrom:f.get('validFrom'),validUntil:f.get('validUntil'),baseMode:f.get('baseMode'),category:f.get('category'),confirmMissingZero:f.has('confirmMissingZero'),date1904:sheet.date1904,siret:db.companies.find(c=>c.id===company)?.siret};showMapping();return false;});}
function showMapping(){const data=pending,headers=data.sheet.rows[data.mapping.headerRow],guessed=OrganismRateImport.guess(headers),labels={label:'Libellé de cotisation',code:'Code rubrique / CTP',employeeRate:'Taux salarié',employerRate:'Taux employeur',baseMode:'Assiette',validFrom:'Date d’effet',validUntil:'Date de fin',category:'Catégorie',siret:'SIRET'};extendedForm(`<h2>Associer les colonnes du fichier</h2><p>${esc(data.mapping.organism)} · ${esc(data.sheet.name)}. Les assiettes acceptées sont brut (gross), tranche 1 (t1), tranche 2 (t2), plafonds 4/8 (cap4/cap8) et CSG (csg). Les règles spécifiques non reconnues demandent une adaptation.</p><div class="fields">${Object.entries(labels).map(([k,label])=>`<label>${esc(label)}<select name="column:${k}">${options(headers,guessed[k])}</select></label>`).join('')}</div>`,f=>{const columns=Object.fromEntries(Object.keys(labels).map(k=>[k,Number(f.get('column:'+k))]));data.rows=OrganismRateImport.parse(data.sheet.rows,{...data.mapping,columns});data.blocked=[];showPreview();return false;});}
function showPreview(){const data=pending,key=tableKey(data.mapping.organism),current=activeTable(key),rows=data.rows;extendedForm(`<h2>Vérifier les taux avant enregistrement</h2><p>${esc(data.mapping.organism)} · ${rows.length} rubrique(s). Seules les lignes cochées seront enregistrées dans le catalogue de l’établissement.</p><div class="scroll"><table><tr><th>Choix</th><th>Rubrique / catégorie</th><th>Valeur actuelle sal. / pat.</th><th>Taux importé sal. / pat.</th><th>Assiette</th><th>Validité</th></tr>${rows.map((r,i)=>{const old=current?.rows.find(v=>OrganismRateImport.exactKey(v)===OrganismRateImport.exactKey(r))||current?.rows.find(v=>OrganismRateImport.key(v)===OrganismRateImport.key(r));return `<tr><td><input type="checkbox" name="selected" value="${i}" aria-label="Importer ${esc(r.label)}"></td><td>${esc(r.label)}<small>${esc(r.code)} · ${esc(r.category)}</small></td><td>${old?esc(old.employeeRate+' % / '+old.employerRate+' %'):'Nouvelle rubrique'}</td><td>${esc(r.employeeRate)} % / ${esc(r.employerRate)} %</td><td>${esc(baseNames[r.baseMode]||r.baseMode)}</td><td>${esc(r.validFrom||'À confirmer')} → ${esc(r.validUntil||'sans fin renseignée')}</td></tr>`;}).join('')}</table></div>${data.blocked?.length?`<details open><summary>${data.blocked.length} rubrique(s) à compléter — non appliquées</summary><table><tr><th>Rubrique</th><th>Total fourni</th><th>À compléter</th></tr>${data.blocked.map(r=>`<tr><td>${esc(r.label)}</td><td>${esc(r.totalRaw)}</td><td>${esc(r.reason)}</td></tr>`).join('')}</table></details>`:''}<label><input type="checkbox" name="reviewed">Je valide les taux, les unités et les parts des lignes cochées. Les dates absentes restent à confirmer avant application.</label><label><input type="checkbox" name="closePrevious">En cas de nouveau taux à effet ultérieur pour la même rubrique, je confirme la clôture de la période précédente la veille du nouveau taux.</label><p class="notice">Enregistrement dans un catalogue de taux uniquement. Les variables et bulletins existants ne seront pas modifiés. L’application à une préparation se fait séparément après vérification.</p>`,f=>{if(!f.has('reviewed'))throw Error('Validez les contrôles avant enregistrement.');const selected=f.getAll('selected').map(i=>rows[Number(i)]);if(!selected.length)throw Error('Cochez au moins une rubrique.');const merged=OrganismRateImport.merge(current?.rows||[],selected,{closePrevious:f.has('closePrevious')}),old=db.organismRateTables[key];if(current&&JSON.stringify(current.rows)===JSON.stringify(merged)){toast('Ces taux sont déjà enregistrés : aucun doublon.');return;}const version={id:crypto.randomUUID(),organism:data.mapping.organism,company,createdAt:new Date().toISOString(),fileName:data.name,fileHash:data.hash,sheet:data.sheet.name,rows:merged,validityConfirmed:merged.every(r=>!!r.validFrom),pendingRows:structuredClone(data.blocked||[])};db.organismRateTables[key]={organism:data.mapping.organism,company,activeVersionId:version.id,versions:[...(old?.versions||[]),version]};if(!save()){if(old)db.organismRateTables[key]=old;else delete db.organismRateTables[key];throw Error('Impossible d’enregistrer le catalogue.');}});}
async function ensureXlsReader(){if(window.XLSX)return;await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=new URL('sheetjs-0.20.3.min.js',assetsBase).href;script.onload=resolve;script.onerror=()=>reject(Error('Lecteur XLS indisponible. Utilisez une copie .xlsx ou CSV.'));document.head.appendChild(script);});}
async function legacyXls(buffer){await ensureXlsReader();const w=XLSX.read(buffer,{type:'array',cellFormula:true,cellHTML:false,bookVBA:false,sheetRows:1000});if(w.SheetNames.length>20)throw Error('Trop de feuilles. Exportez uniquement les taux.');return w.SheetNames.map(name=>{const sheet=w.Sheets[name],range=XLSX.utils.decode_range(sheet['!ref']||'A1');if(range.e.c>99||range.e.r>999)throw Error('Feuille trop grande pour un import de taux.');const rows=[];for(let r=0;r<=range.e.r;r++){const row=[];for(let c=0;c<=range.e.c;c++){const cell=sheet[XLSX.utils.encode_cell({r,c})];if(cell?.f)throw Error('Formules détectées : fournir une copie en valeurs.');row[c]=cell?.w&&/%|€/.test(cell.w)?cell.w:cell?.v??'';}rows.push(row);}return{name,rows,date1904:!!w.Workbook?.WBProps?.date1904};});}
async function readFile(file){if(!file)return;try{if(file.size>2000000)throw Error('Maximum 2 Mo. Réduisez le fichier aux taux à importer.');const buffer=await file.arrayBuffer(),hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',buffer))).map(n=>n.toString(16).padStart(2,'0')).join('');let sheets;if(/\.xlsx$/i.test(file.name))sheets=await TimeImport.xlsx(buffer);else if(/\.xls$/i.test(file.name))sheets=await legacyXls(buffer);else if(/\.csv$/i.test(file.name)){let text=new TextDecoder().decode(buffer);if(text.includes('\uFFFD'))text=new TextDecoder('windows-1252').decode(buffer);sheets=[{name:'CSV',rows:TimeImport.csv(text)}];}else throw Error('Fournissez un .xls, .xlsx ou .csv.');pending={name:file.name,sheets,hash};const type=OrganismExportAdapters.kind(sheets[0].rows);if(type==='atmp')showAtmpPreview();else if(type==='probtp')showProBtp();else chooseSheet();}catch(e){toast(e.message);}}
function showAtmpPreview(){const companyRecord=db.companies.find(c=>c.id===company),data=pending,proposal=OrganismExportAdapters.atmp(data.sheets[0].rows,companyRecord.siret);extendedForm(`<h2>Importer la notification AT/MP</h2><p>${esc(data.name)} · SIRET ${esc(proposal.siret)}</p><table><tr><th>Donnée</th><th>Actuelle</th><th>Export</th></tr>${[['Taux employeur',companyRecord.atmpRate,proposal.atmpRate+' %'],['Code risque',companyRecord.atmpRiskCode,proposal.atmpRiskCode],['Date d’effet',companyRecord.atmpValidFrom,proposal.atmpValidFrom],['Date de décision',companyRecord.atmpDecisionDate,proposal.atmpDecisionDate],['Date de notification',companyRecord.atmpNotificationDate,proposal.atmpNotificationDate]].map(([l,a,v])=>`<tr><td>${esc(l)}</td><td>${esc(a||'Non renseigné')}</td><td>${esc(v||'Non renseigné')}</td></tr>`).join('')}</table><p class="notice">La date d’effet est distincte de la notification. Aucun ancien bulletin n’est modifié ; le prochain calcul lit la fiche entreprise.</p><label><input type="checkbox" name="confirm">Je confirme l’établissement, le taux, le code risque et les dates.</label>`,f=>{if(!f.has('confirm'))throw Error('Validez les données AT/MP.');const before=structuredClone(companyRecord);db.organismNotificationHistory=db.organismNotificationHistory||[];db.organismNotificationHistory.push({company,at:new Date().toISOString(),sourceFile:data.name,sourceHash:data.hash,before});Object.assign(companyRecord,proposal,{atmpReference:'Import '+data.name+' · décision '+proposal.atmpDecisionDate+' · notification '+proposal.atmpNotificationDate});if(!save()){Object.assign(companyRecord,before);db.organismNotificationHistory.pop();throw Error('Enregistrement impossible.');}});}
function showProBtp(){const data=pending;extendedForm(`<h2>Feuille de taux PRO BTP reconnue</h2><p>${esc(data.name)} · les colonnes Population, Produit, Part employeur, Part salarié et Taux cotisé sont reconnues.</p><p class="notice">Le fichier ne précise pas de date d’effet. La date du nom de fichier est une date d’export, pas une date de validité. Renseignez la période confirmée par votre contrat ou notification, ou laissez-la à confirmer. Le catalogue peut être conservé sans date, mais ne sera pas applicable à la paie.</p>${field('validFrom','Date d’effet (laisser vide si à confirmer)','','date')}${field('validUntil','Fin de validité si connue','','date')}<p>Les totaux sans répartition, les forfaits en euros et les assiettes non définies resteront « à compléter ». Ils ne seront pas transformés en pourcentages.</p>`,f=>{const parsed=OrganismExportAdapters.probtp(data.sheets[0].rows,f.get('validFrom'),f.get('validUntil'));data.sheet=data.sheets[0];data.mapping={organism:'PRO BTP'};data.rows=parsed.rows;data.blocked=parsed.pending;showPreview();return false;});}
function importButton(){const input=document.createElement('input');input.type='file';input.accept='.xls,.xlsx,.csv';input.hidden=true;input.onchange=()=>{readFile(input.files[0]);input.remove();};document.body.appendChild(input);input.click();}
function useCatalog(){const tables=Object.keys(db.organismRateTables).filter(k=>db.organismRateTables[k].company===company&&activeTable(k));if(!tables.length){toast('Importez d’abord un catalogue depuis la fiche entreprise.');return;}const ps=people().filter(p=>DsnPreparation.inPeriod(p,period()));if(!ps.length){toast('Ajoutez un salarié.');return;}extendedForm(`<h2>Utiliser les taux importés</h2><p>Choisissez la préparation enregistrée à mettre à jour pour ${esc(period())}. Les anciens bulletins restent conservés.</p><label>Salarié<select name="person">${ps.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label><label>Catalogue<select name="catalog">${tables.map(k=>`<option value="${esc(k)}">${esc(db.organismRateTables[k].organism)} · ${esc(new Date(activeTable(k).createdAt).toLocaleString('fr-FR'))}</option>`).join('')}</select></label>`,f=>{const p=ps.find(p=>p.id===f.get('person')),catalog=activeTable(f.get('catalog')),rows=OrganismRateImport.applicable(catalog.rows,p,period());previewApplication(p,catalog,rows);return false;});}
function previewApplication(p,catalog,rows){const old=db.vars[vkey(p)],current=richVar(p),companyRecord=db.companies.find(c=>c.id===company),next=structuredClone(current.rows||[]);const preview=[];for(const row of rows){const isAt=/accident.*travail|AT\/MP/i.test(row.label);if(isAt){const registered=String(companyRecord.atmpRate??'').replace(',','.');if(registered===''||Number(registered)!==Number(row.employerRate))throw Error('Taux AT/MP différent de la fiche entreprise : mettez d’abord à jour et contrôlez la fiche entreprise.');}
 const importKey=catalog.organism+'|'+OrganismRateImport.key(row),at=next.findIndex(r=>r.organismImportKey===importKey||OrganismRateImport.norm(r.label)===OrganismRateImport.norm(row.label)),before=at>=0?next[at]:null,item={...row,organismImportKey:importKey,organismImportVersion:catalog.id,csgInclude:before?.csgInclude||'À vérifier'};preview.push({row,before});if(at>=0)next[at]=item;else next.push(item);}
 extendedForm(`<h2>Appliquer les taux à la préparation</h2><p>${esc(p.name)} · ${esc(period())} · ${esc(catalog.organism)}</p><div class="scroll"><table><tr><th>Rubrique</th><th>Actuel salarié / employeur</th><th>Proposé salarié / employeur</th></tr>${preview.map(({row,before})=>`<tr><td>${esc(row.label)}</td><td>${before?esc(before.employeeRate+' / '+before.employerRate):'Ajout'}</td><td>${esc(row.employeeRate)} % / ${esc(row.employerRate)} %</td></tr>`).join('')}</table></div><label><input type="checkbox" name="confirm">Je confirme l’application à cette préparation, après contrôle des doublons, des assiettes et de la réintégration CSG.</label><p class="muted">Le statut revient à « À vérifier ». Aucun bulletin historique n’est recalculé. Les régularisations et règles spécifiques restent à contrôler.</p>`,f=>{if(!f.has('confirm'))throw Error('Confirmez la préparation et les taux.');db.rateApplicationHistory=db.rateApplicationHistory||[];db.rateApplicationHistory.push({company,period:period(),personId:p.id,at:new Date().toISOString(),previous:structuredClone(old||null),catalogVersion:catalog.id});db.vars[vkey(p)]={...current,rows:next,cotReviewed:'À vérifier',status:'À vérifier'};if(!save()){if(old)db.vars[vkey(p)]=old;else delete db.vars[vkey(p)];db.rateApplicationHistory.pop();throw Error('Enregistrement impossible.');}});}
function rollbackCatalog(key){const t=db.organismRateTables[key],current=activeTable(key),index=t.versions.findIndex(v=>v.id===current.id),previous=t.versions[index-1];if(!previous)return;extendedForm(`<h2>Revenir au catalogue précédent</h2><p>${esc(t.organism)} : restaurer les ${previous.rows.length} rubriques de la version du ${esc(new Date(previous.createdAt).toLocaleString('fr-FR'))} ?</p><p class="notice">Cette action concerne seulement le catalogue. Les préparations auxquelles les taux ont déjà été appliqués demandent un contrôle séparé.</p><label><input type="checkbox" name="confirm">Je confirme la restauration du catalogue précédent.</label>`,f=>{if(!f.has('confirm'))throw Error('Confirmez la restauration.');const restored={...structuredClone(previous),id:crypto.randomUUID(),createdAt:new Date().toISOString(),restoredFrom:previous.id};t.versions.push(restored);t.activeVersionId=restored.id;if(!save()){t.versions.pop();t.activeVersionId=current.id;throw Error('Enregistrement impossible.');}});}
function confirmCatalogDates(key){const t=db.organismRateTables[key],current=activeTable(key);extendedForm(`<h2>Confirmer la période des taux</h2><p>${esc(t.organism)} : les taux sans date ne sont pas utilisables pour la préparation. La date d’export ne remplace pas la date d’effet.</p>${field('validFrom','Date d’effet confirmée','','date','required')}${field('validUntil','Fin de validité si connue','','date')}<label><input type="checkbox" name="confirm">Je confirme que cette période correspond au contrat ou à la notification de l’organisme.</label>`,f=>{if(!f.has('confirm'))throw Error('Confirmez la période.');const from=OrganismRateImport.date(f.get('validFrom')),until=OrganismRateImport.date(f.get('validUntil'),false,true);if(until&&until<from)throw Error('Période invalide.');const next={...structuredClone(current),id:crypto.randomUUID(),createdAt:new Date().toISOString(),validityConfirmed:true,rows:current.rows.map(r=>r.validFrom?r:{...r,validFrom:from,validUntil:until})};t.versions.push(next);t.activeVersionId=next.id;if(!save()){t.versions.pop();t.activeVersionId=current.id;throw Error('Enregistrement impossible.');}});}
function renderParameters(){document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.textContent===parametersLabel));const c=db.companies.find(c=>c.id===company),profiles=people().map(p=>({p,v:db.vars[vkey(p)]})).filter(x=>x.v?.rows?.length);$('#app').innerHTML=head('Paramètres de cotisations.','Taux, sources, périodes de validité et imports des organismes.')+`<section class="panel"><h2>Établissement · ${esc(c.name)}</h2><table><tr><th>AT/MP employeur</th><th>Code risque</th><th>Date d’effet</th><th>Notification</th></tr><tr><td>${esc(c.atmpRate||'À renseigner')} %</td><td>${esc(c.atmpRiskCode||'À renseigner')}</td><td>${esc(c.atmpValidFrom||'À renseigner')}</td><td>${esc(c.atmpNotificationDate||'À renseigner')}</td></tr></table><div class="tools"><button class="btn secondary" type="button" id="parameterCompany">Modifier la fiche entreprise</button></div></section><section class="panel" style="margin-top:20px"><h2>Taux des préparations enregistrées · ${esc(period())}</h2><p>URSSAF, PRO BTP, CIBTP et autres organismes : les taux enregistrés restent rattachés à leur préparation. Les imports validés ci-dessous constituent un catalogue distinct avant application.</p>${profiles.map(({p,v},i)=>`<details><summary>${esc(p.name)} · ${v.rows.length} lignes</summary><div class="scroll"><table><tr><th>Rubrique</th><th>Part salarié %</th><th>Part employeur %</th><th>Assiette</th></tr>${v.rows.map(r=>`<tr><td>${esc(r.label)}</td><td>${esc(r.employeeRate)}</td><td>${esc(r.employerRate)}</td><td>${esc(baseNames[r.baseMode]||r.baseMode)}</td></tr>`).join('')}</table></div><button class="btn secondary" type="button" data-edit-profile="${i}">Modifier ces taux dans la préparation</button></details>`).join('')||'<p>Aucun taux encore enregistré pour ce mois.</p>'}</section>`;$('#parameterCompany').onclick=companyEdit;document.querySelectorAll('[data-edit-profile]').forEach(b=>b.onclick=()=>variable(profiles[Number(b.dataset.editProfile)].p.id));}
const oldRender=render;render=function(){if(view===parametersLabel)renderParameters();else oldRender();if(!['Entreprise','Préparation paie',parametersLabel].includes(view))return;const panel=document.createElement('section');panel.className='panel rate-import-panel';const tables=Object.keys(db.organismRateTables).filter(k=>db.organismRateTables[k].company===company);panel.innerHTML=`<h2>Importer les taux des organismes</h2><p>PRO BTP, URSSAF ou autre organisme · fichiers Excel (.xls / .xlsx) et CSV · correspondance des colonnes et contrôle avant validation.</p><div class="tools"><button type="button" class="btn" id="importOrganismRates">Importer des taux Excel / CSV</button><button type="button" class="btn secondary" id="organismRateModel">Télécharger le modèle CSV pour Excel</button>${tables.length?'<button type="button" class="btn secondary" id="useOrganismRates">Utiliser les taux importés en préparation</button>':''}</div><p class="muted">Aucune connexion directe à PRO BTP ou à l’URSSAF. Un export inconnu peut demander une adaptation. L’import ne valide pas les règles de paie et ne remplace pas automatiquement le taux AT/MP de la fiche entreprise.</p>${tables.map((k,i)=>{const v=activeTable(k),t=db.organismRateTables[k];return `<div class="rate-catalog"><strong>${esc(t.organism)}</strong> · ${v.rows.length} rubriques prêtes${v.pendingRows?.length?' · '+v.pendingRows.length+' à compléter':''} · import du ${esc(new Date(v.createdAt).toLocaleString('fr-FR'))}${v.validityConfirmed===false?` <button type="button" class="btn secondary" data-confirm-dates="${i}">Confirmer les dates d’effet</button>`:''}${t.versions.length>1?` <button type="button" class="btn secondary" data-rollback="${i}">Catalogue précédent</button>`:''}<details><summary>Consulter les taux et leur validité</summary><div class="scroll"><table><tr><th>Rubrique</th><th>Salarié %</th><th>Employeur %</th><th>Catégorie</th><th>Validité</th></tr>${v.rows.map(r=>`<tr><td>${esc(r.label)}</td><td>${esc(r.employeeRate)}</td><td>${esc(r.employerRate)}</td><td>${esc(r.category)}</td><td>${esc(r.validFrom||'À confirmer')} → ${esc(r.validUntil||'')}</td></tr>`).join('')}</table>${v.pendingRows?.length?`<h3>À compléter, non appliqué</h3><table>${v.pendingRows.map(r=>`<tr><td>${esc(r.label)}</td><td>${esc(r.totalRaw)}</td><td>${esc(r.reason)}</td></tr>`).join('')}</table>`:''}</div></details></div>`;}).join('')}`;$('#app').appendChild(panel);panel.querySelector('#importOrganismRates').onclick=importButton;panel.querySelector('#organismRateModel').onclick=()=>download('modele-taux-organismes.csv','\uFEFFLibellé;Code;Taux salarié;Taux employeur;Assiette;Date effet;Date fin;Catégorie;SIRET\r\nExemple de cotisation TEST;TEST;1,00;2,00;gross;2026-01-01;;Tous;\r\n','text/csv;charset=utf-8');const apply=panel.querySelector('#useOrganismRates');if(apply)apply.onclick=useCatalog;panel.querySelectorAll('[data-confirm-dates]').forEach(b=>b.onclick=()=>confirmCatalogDates(tables[Number(b.dataset.confirmDates)]));panel.querySelectorAll('[data-rollback]').forEach(b=>b.onclick=()=>rollbackCatalog(tables[Number(b.dataset.rollback)]));};const parameterNav=document.createElement('button');parameterNav.textContent=parametersLabel;parameterNav.onclick=()=>go(parametersLabel);$('#nav').appendChild(parameterNav);if(new URLSearchParams(location.search).get('onglet')==='parametres')view=parametersLabel;render();
})();
